<!-- This file is generated by AI. -->

<!--
  状态栏: LSP 状态、(配音工作台打开时的) GSOV 状态、诊断数、光标位置、字数与行数。

  GSOV 状态**只在配音工作台打开时出现**: 未启用配音时状态栏保持干净; 工作台一旦打开, 无论是否
  停在场景卡上都能在底部看到服务是否就绪。

  它和 LSP 那一项是同一种东西: **名称 + 一句话状态**, 不承载计数 —— 待处理的配音任务数属于
  "工作台里正在发生什么", 由工作台选项卡的角标负责。

  诊断数是**整个项目**的合计 (含未打开的场景), 不是当前那张卡的。
-->

<script lang="ts">
  import { collectProjectDiagnostics } from '../diagnostics/model';
  import { isVoiceWorkbenchOpen } from '../state/selectors';
  import { actions, appStore } from '../state/store.svelte';
  import { voiceController } from '../voice/controller';

  const GSV_LABELS: Record<string, string> = {
    ready: '就绪',
    starting: '启动中…',
    stopping: '停止中…',
    error: '错误',
    stopped: '未启动',
  };

  const workbenchOpen = $derived(isVoiceWorkbenchOpen(appStore.tabs));
  const activeTab = $derived(appStore.tabs.find((item) => item.id === appStore.activeTabId) ?? null);
  const activeDoc = $derived(
    activeTab?.kind === 'scene' ? (appStore.documents.find((doc) => doc.path === activeTab.path) ?? null) : null
  );

  /** 整个项目的错误与警告数 (信息级不计入: 它数量最多且不代表"坏了")。 */
  const projectDiagnostics = $derived.by(() => {
    const { files } = collectProjectDiagnostics(appStore.diagnostics, appStore.projectPath);
    let problems = 0;
    let errors = 0;
    for (const file of files) {
      for (const entry of file.entries) {
        if (entry.severity === 1) {
          errors += 1;
          problems += 1;
        } else if (entry.severity === 2) {
          problems += 1;
        }
      }
    }
    return { problems, errors };
  });

  const isNovel = $derived(activeTab?.kind === 'novel');
  const charCount = $derived(isNovel ? (appStore.novelStats?.chars ?? 0) : (activeDoc?.content.length ?? 0));
  const lineCount = $derived(
    isNovel ? (appStore.novelStats?.lines ?? 0) : activeDoc ? activeDoc.content.split('\n').length : 0
  );

  const lspLabel = $derived(
    appStore.lspActivity
      ? '响应缓慢'
      : appStore.lspStatus === 'ready'
        ? '就绪'
        : appStore.lspStatus === 'connecting'
          ? '连接中'
          : appStore.lspStatus === 'error'
            ? '错误'
            : '未连接'
  );

  /**
   * 是否有一条任务**正在推理**。
   *
   * ⚠️ 必须读 `appStore.voiceTick`: 控制器是就地改任务对象的 (`task.status = 'running'`), 只有
   * 它每次生命周期都自增的令牌能驱动重算 —— 否则这一项永远停在"就绪"。
   *
   * 只认 `running` 而不认"排队中": 排队还没开始生成, 这时显示服务本身的状态才是诚实的;
   * 待处理的条数由工作台选项卡角标负责。
   */
  const generating = $derived.by(() => {
    void appStore.voiceTick;
    return voiceController.allTasks().some((task) => task.status === 'running');
  });

  /** 生成中时优先显示它; 其余情况显示服务状态 */
  const gsvLabel = $derived(generating ? '生成中…' : (GSV_LABELS[appStore.voiceStatus] ?? appStore.voiceStatus));
  const gsvTone = $derived(generating ? 'generating' : appStore.voiceStatus);
</script>

<div class="status-bar" title={appStore.lspActivity ?? appStore.lspError ?? appStore.voiceStatusDetail ?? undefined}>
  <!--
    "就绪"说的是连接, 不是"答得上来": 语言服务处理大批文件变更时会长时间不答复任何请求, 这时照旧
    写"就绪"等于骗人 —— 有请求超时未答就改说"响应缓慢", 答复一到自动恢复。
  -->
  <span
    class="lsp-status"
    class:lsp-syncing={appStore.lspActivity}
    class:lsp-ready={appStore.lspStatus === 'ready'}
    class:lsp-error={appStore.lspStatus === 'error'}
    class:lsp-connecting={appStore.lspStatus === 'connecting'}
  >
    LSP: {lspLabel}
  </span>

  <!--
    「停止中…」要在工作台已经关掉之后继续显示一会儿: 关闭工作台会顺手停掉 GSOV, 而进程收尾需要
    时间 —— 这一项立刻消失的话, 用户看到的是"点了关闭、服务还在, 然后突然没了"。

    「生成中…」则与工作台开不开无关: 生成从场景卡的配音模式发起, 用户完全可以关掉工作台 ——
    那时底部状态栏是他唯一能看到"还在跑"的地方。
  -->
  {#if workbenchOpen || appStore.voiceStatus === 'stopping' || generating}
    <span class="status-voice status-voice-{gsvTone}">GSOV: {gsvLabel}</span>
  {/if}

  <button
    type="button"
    class="status-diag"
    class:open={appStore.diagnosticsOpen}
    title="查看整个项目的诊断（不含信息级与提示）"
    aria-expanded={appStore.diagnosticsOpen}
    onclick={() => actions.setDiagnosticsOpen(!appStore.diagnosticsOpen)}
  >
    诊断: {projectDiagnostics.problems}{projectDiagnostics.errors > 0 ? ` (错误 ${projectDiagnostics.errors})` : ''}
  </button>

  <span class="status-spacer"></span>

  {#if appStore.cursor}
    <span class="status-cursor">行 {appStore.cursor.line}, 列 {appStore.cursor.column}</span>
  {/if}
  <span class="status-chars">字符 {charCount}</span>
  <span class="status-lines">行数 {lineCount}</span>
</div>
